  /** M85：召回钻取 → 单需求重跑旁路（绕开整批） */
  @Post('recall-pool-hit-rate/drill/rerun')
  async recallPoolHitDrillRerun(
    @Req() req: any,
    @Body()
    body: {
      demandId?: string;
      topN?: number;
      minScore?: number;
      dryRun?: boolean;
      percentile?: string;
      band?: string;
    } = {},
  ) {
    const tenantId = req?.user?.tenantId || req?.resolvedTenantId || 'default';
    let demandId = String(body?.demandId || '').trim();
    if (!demandId) {
      const drill = recallPoolHitRateDrillToDemandIds(tenantId, {
        percentile: (body?.percentile as any) || 'p10',
        band: (body?.band as any) || 'low',
        limit: 1,
      });
      demandId = String(drill.demandIds?.[0] || '').trim();
    }
    if (!demandId) {
      return {
        ok: false,
        dryRun: true,
        noEgress: true,
        wave: 'M85',
        labelZh: '单需求重跑旁路',
        tipZh: '无 demandId 可重跑；请先钻取或传入 demandId',
        toastZh: '无可重跑需求',
        busyZh: '单需求重跑旁路…',
        bypassFullBatch: true,
        softCancelIntact: true,
      };
    }
    if (body?.dryRun === true || !this.matches) {
      let beforeRows: any[] = [];
      try {
        if (this.matches && typeof (this.matches as any).prisma?.match?.findMany === 'function') {
          beforeRows = await (this.matches as any).prisma.match.findMany({
            where: { demandId },
            orderBy: { totalScore: 'desc' },
            take: body?.topN ?? 3,
            include: { capability: { include: { org: true } }, outcome: { include: { org: true } } },
          });
          beforeRows = beforeRows.map((m: any) => ({
            matchId: m.id,
            supplyId: m.capabilityId || m.outcomeId,
            title: m.capability?.title || m.outcome?.title,
            orgName: m.capability?.org?.name || m.outcome?.org?.name,
            kind: m.capabilityId ? 'capability' : 'outcome',
            score: m.totalScore,
          }));
        }
      } catch (_) {
        beforeRows = [];
      }
      const afterRows = simulateBypassAfterForDryRun(beforeRows, body?.topN ?? 3);
      const board = persistBypassContrastBoard(tenantId, demandId, beforeRows, afterRows, {
        topN: body?.topN ?? 3,
        dryRun: true,
      });
      return {
        ok: true,
        dryRun: true,
        noEgress: true,
        wave: 'M87',
        labelZh: '单需求重跑旁路（干跑）',
        tipZh: `将仅重跑 demandId=${demandId}，绕开整批；软取消仍在 · ${board.summaryZh}`,
        toastZh: `干跑旁路 · ${demandId}`,
        busyZh: '单需求重跑旁路…',
        bypassFullBatch: true,
        softCancelIntact: true,
        demandId,
        runPath: '/api/matches/run',
        body: { demandId, topN: body?.topN ?? 3, minScore: body?.minScore ?? 0.1, bypassFullBatch: true },
        contrastBoard: board,
        contrastBoardPath: '/api/metrics/recall-pool-hit-rate/drill/rerun/contrast-board',
        contrastBoardLabelZh: '单需求旁路结果对照看板',
      };
    }
    let beforeRows: any[] = [];
    try {
      beforeRows = await (this.matches as any).prisma.match.findMany({
        where: { demandId },
        orderBy: { totalScore: 'desc' },
        take: body?.topN ?? 3,
        include: { capability: { include: { org: true } }, outcome: { include: { org: true } } },
      });
      beforeRows = beforeRows.map((m: any) => ({
        matchId: m.id,
        supplyId: m.capabilityId || m.outcomeId,
        title: m.capability?.title || m.outcome?.title,
        orgName: m.capability?.org?.name || m.outcome?.org?.name,
        kind: m.capabilityId ? 'capability' : 'outcome',
        score: m.totalScore,
      }));
    } catch (_) {
      beforeRows = [];
    }
    const result = await this.matches.runMatch({
      demandId,
      demandIds: [demandId],
      topN: body?.topN ?? 3,
      minScore: body?.minScore ?? 0.1,
    });
    const afterRows = (result?.items || []).map((it: any) => ({
      matchId: it.id || it.matchId,
      supplyId: it.capabilityId || it.outcomeId || it.supplyId,
      title: it.capability?.title || it.outcome?.title || it.supplyTitle || it.title,
      orgName: it.capability?.org?.name || it.outcome?.org?.name || it.supplyOrg || it.orgName,
      kind: it.capabilityId ? 'capability' : it.outcomeId ? 'outcome' : it.kind,
      score: it.totalScore ?? it.score,
    }));
    const board = persistBypassContrastBoard(tenantId, demandId, beforeRows, afterRows, {
      topN: body?.topN ?? 3,
      dryRun: false,
    });
    return {
      ...result,
      ok: true,
      wave: 'M87',
      labelZh: '单需求重跑旁路',
      tipZh: `已仅重跑 demandId=${demandId}（绕开整批）· 软取消仍在 · ${board.summaryZh}`,
      toastZh: `单需求重跑完成 · ${demandId}`,
      busyZh: '单需求重跑旁路…',
      bypassFullBatch: true,
      softCancelIntact: true,
      demandId,
      singleDemandRerun: true,
      contrastBoard: board,
      contrastBoardPath: '/api/metrics/recall-pool-hit-rate/drill/rerun/contrast-board',
      contrastBoardLabelZh: '单需求旁路结果对照看板',
    };
  }

