  /** M84/M85：异常串联分项进度真 EventSource；M85 支持 Last-Event-ID 断线续订 + 分项对照 */
  @Get('inbox-delta-cache/curve/alerts/shell-health/weekly-sparkline/day-drill/trend-anomaly/chain-bust-reprobe/stream')
  async anomalyChainStream(@Req() req: any, @Res() res: Response, @Query('lastEventId') lastEventIdQ?: string) {
    const tenantId = req?.user?.tenantId || req?.resolvedTenantId || 'default';
    const authed = Boolean(
      req?.user || req?.authViaSseTicket || req?.authViaQueryToken || req?.headers?.authorization,
    );
    if (!authed) {
      res.status(401).json({
        ok: false,
        messageZh:
          '进度推送需要登录：请带登录 cookie、Authorization: Bearer，或先 POST /api/jobs/sse-ticket 再用 ?sse_ticket=…',
        wave: 'M85',
      });
      return;
    }
    res.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
    res.setHeader('Cache-Control', 'no-cache, no-transform');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no');
    res.setHeader(
      'X-Yanqi-Sse-Auth',
      req?.authViaSseTicket ? 'sse-ticket' : req?.authViaQueryToken ? 'query-token' : 'session',
    );
    res.setHeader('X-Yanqi-Sse-Reconnect', 'last-event-id');
    if (typeof (res as any).flushHeaders === 'function') (res as any).flushHeaders();

    let closed = false;
    const onClose = () => {
      closed = true;
    };
    req.on('close', onClose);

    const lastFromHeader = req?.headers?.['last-event-id'] || req?.headers?.['Last-Event-ID'];
    const lastEventId = lastEventIdQ || lastFromHeader || null;

    const writeEvt = (ev: { id: number; event: string; payload: any }) => {
      if (closed) return;
      res.write(`id: ${ev.id}\nevent: ${ev.event}\ndata: ${JSON.stringify(ev.payload)}\n\n`);
    };

    // 断线续订：先回放 lastEventId 之后的环内事件
    const replayed = replayAnomalySseAfter(tenantId, lastEventId);
    if (replayed.length) {
      const resumeRow = pushAnomalySseEvent(tenantId, 'resume', {
        ok: true,
        dryRun: true,
        noEgress: true,
        wave: 'M85',
        labelZh: '异常 EventSource 断线续订',
        tipZh: `已续订：回放 ${replayed.length} 条（自 lastEventId=${lastEventId}）`,
        toastZh: `续订回放 ${replayed.length}`,
        replayCount: replayed.length,
        lastEventId: Number(lastEventId) || 0,
        resume: true,
      });
      writeEvt(resumeRow);
      for (const ev of replayed) writeEvt(ev);
    }

    const send = () => {
      if (closed) return true;
      const card = getAnomalyChainJobCard(tenantId);
      const job = card.job;
      const waiting =
        job &&
        (job.status === 'queued' || job.status === 'running' || job.status === 'cancelling');
      const itemized = card.itemizedPhases || job?.itemizedPhases || null;
      const itemizedContrast = buildAnomalyItemizedPhaseContrast(itemized as any, job?.status || null);
      const payload = {
        ok: true,
        waiting: Boolean(waiting),
        dryRun: true,
        noEgress: true,
        wave: 'M85',
        labelZh: '异常串联分项 EventSource（可断线续订）',
        tipZh: card.tipZh,
        toastZh: card.toastZh,
        percent: job?.percent ?? null,
        phase: job?.phase ?? null,
        status: job?.status ?? null,
        itemizedPhases: itemized,
        itemizedPhasesSse: true,
        itemizedPhasesEventSource: true,
        itemizedContrast,
        itemizedContrastLabelZh: '分项 expected×actual 对照',
        sseReconnect: true,
        sseReconnectVia: 'Last-Event-ID',
        cancelResumeIntact: true,
        streamPath:
          '/api/metrics/inbox-delta-cache/curve/alerts/shell-health/weekly-sparkline/day-drill/trend-anomaly/chain-bust-reprobe/stream',
        job,
      };
      const row = pushAnomalySseEvent(tenantId, 'progress', payload);
      writeEvt(row);
      return !waiting;
    };

    try {
      let done = send();
      let ticks = 0;
      while (!done && !closed && ticks < 120) {
        await new Promise((r) => setTimeout(r, 700));
        ticks += 1;
        done = send();
      }
      if (!closed) {
        const endRow = pushAnomalySseEvent(tenantId, 'end', { ok: true, wave: 'M85', dryRun: true, noEgress: true });
        writeEvt(endRow);
      }
    } catch (e: any) {
      if (!closed) {
        const errRow = pushAnomalySseEvent(tenantId, 'error', {
          ok: false,
          message: String(e?.message || e).slice(0, 200),
          wave: 'M85',
        });
        writeEvt(errRow);
      }
    } finally {
      req.off('close', onClose);
      if (!closed) res.end();
    }
  }

