  /** M86：对照行一键重跑 bust/复探针等阶段（干跑、无外发） */
  @Post('inbox-delta-cache/curve/alerts/shell-health/weekly-sparkline/day-drill/trend-anomaly/chain-bust-reprobe/itemized-contrast/rerun-row')
  anomalyItemizedContrastRerunRow(
    @Req() req: any,
    @Body()
    body: {
      phase?: string;
      id?: string;
      shells?: string[] | null;
      force?: boolean;
      dryRun?: boolean;
      notifyDryRun?: boolean;
    } = {},
  ) {
    const tenantId = req?.user?.tenantId || req?.resolvedTenantId || 'default';
    const phase = String(body?.phase || body?.id || '').trim() || 'bust';
    const meta = anomalyContrastRowRerunMeta(phase);
    let step: any = null;
    if (phase === 'attribution') {
      step = trendDeltaAnomalyAttributionDryRun(tenantId, { multiDay: true });
    } else if (phase === 'bust') {
      step = executeSuggestedBustDryRun(tenantId, {
        shells: body?.shells || null,
        force: body?.force === true,
        autoHitProbe: false,
        notifyDryRun: body?.notifyDryRun !== false,
      });
    } else if (phase === 'reprobe') {
      step = executeSuggestedBustDryRun(tenantId, {
        shells: body?.shells || null,
        force: body?.force === true,
        autoHitProbe: true,
        notifyDryRun: body?.notifyDryRun !== false,
      });
    } else if (phase === 'heal') {
      step = maybeChainSlaOverdueSelfHealAfterProbeFail({
        tenantId,
        shells: body?.shells || null,
        force: true,
        notifyDryRun: body?.notifyDryRun !== false,
        hitProbe: { probeFailed: true, hitRatePct: 0 },
      });
      if (!step || step.chained === false || step.skipped) {
        step = {
          ...selfHealInboxDeltaAlertingShells({ allAlerting: true, shells: body?.shells || null }),
          chainedFromContrastRow: true,
        };
      }
    } else {
      return { ...meta, ok: false, tipZh: `未知阶段 ${phase}`, toastZh: '未知对照行阶段' };
    }
    const card = getAnomalyChainJobCard(tenantId);
    const contrast = buildAnomalyItemizedPhaseContrast(
      (card.itemizedPhases || card.job?.itemizedPhases) as any,
      card.job?.status || null,
    );
    return {
      ...meta,
      ok: true,
      step,
      contrast,
      cancelResumeIntact: true,
      dryRun: true,
      noEgress: true,
    };
  }

