  @Post('ann-bp-hysteresis/write-shard-cooldown/bp-pctile-sparkline/day-drill/suggest-bust-chain')
  cooldownDaySuggestBustChainPost(
    @Req() req: any,
    @Body()
    body: {
      day?: string;
      index?: number;
      at?: string;
      enqueue?: boolean;
      runNow?: boolean;
      maxSteps?: number;
      dryRun?: boolean;
      simulateFail?: boolean;
      failPhase?: string;
      failReasonZh?: string;
      failSimulatePhases?: string[];
    } = {},
  ) {
    const tenantId = req?.user?.tenantId || req?.resolvedTenantId || 'default';
    const plan = suggestBustChainFromCooldownSparkDay(tenantId, body || {});
    if (!body?.enqueue) return plan;
    const phases = plan.suggestedBustChain?.phases || ['bust', 'reprobe'];
    const enq = enqueueAnomalyContrastBatchRerun(tenantId, {
      phases,
      dryRun: true,
      retryBudget: 2,
      failSimulatePhases: body?.failSimulatePhases || (body?.simulateFail ? [body?.failPhase || phases[0] || 'bust'] : null),
    });
    if (!enq.ok) {
      const attribution = attributeSuggestBustChainFailure(tenantId, {
        day: body?.day,
        index: body?.index,
        at: body?.at,
        enqueueResult: enq,
        simulateFail: body?.simulateFail === true,
        failPhase: body?.failPhase || null,
        failReasonZh: body?.failReasonZh || null,
      });
      return {
        ...plan,
        wave: 'M91' as const,
        enqueue: enq,
        failed: true,
        attributionCard: attribution.attributionCard,
        tipZh: (plan.tipZh || '') + ' · ' + attribution.attributionCard.bodyZh,
        toastZh: attribution.toastZh,
        softCancelIntact: true,
        noEgress: true,
        dryRun: true,
      };
    }
    const runStep = (phase: string) => {
      const meta = anomalyContrastRowRerunMeta(phase);
      let step: any = null;
      if (phase === 'attribution') step = trendDeltaAnomalyAttributionDryRun(tenantId, { multiDay: true });
      else if (phase === 'bust')
        step = executeSuggestedBustDryRun(tenantId, { force: false, autoHitProbe: false, notifyDryRun: true });
      else if (phase === 'reprobe')
        step = executeSuggestedBustDryRun(tenantId, { force: false, autoHitProbe: true, notifyDryRun: true });
      else if (phase === 'heal')
        step = maybeChainSlaOverdueSelfHealAfterProbeFail({
          tenantId,
          force: true,
          notifyDryRun: true,
          hitProbe: { probeFailed: true, hitRatePct: 0 },
        });
      else step = meta;
      return { ...meta, step, dryRun: true, noEgress: true };
    };
    let tick: any = null;
    if (body?.runNow !== false) {
      tick = tickAnomalyContrastBatchRerun(tenantId, {
        maxSteps: body?.maxSteps ?? 8,
        runStep,
      });
    }
    const failedItems = (tick?.queue?.items || tick?.items || []).filter((i: any) => i?.status === 'failed');
    const failed = !enq.ok || (failedItems && failedItems.length > 0) || body?.simulateFail === true;
    let attribution: any = null;
    if (failed) {
      attribution = attributeSuggestBustChainFailure(tenantId, {
        day: body?.day,
        index: body?.index,
        at: body?.at,
        enqueueResult: enq,
        tickResult: tick,
        simulateFail: body?.simulateFail === true,
        failPhase: body?.failPhase || failedItems?.[0]?.phase || null,
        failReasonZh: body?.failReasonZh || null,
      });
    }
    return {
      ...plan,
      wave: failed ? ('M91' as const) : ('M90' as const),
      enqueued: true,
      enqueue: enq,
      tick,
      failed: !!failed,
      attributionCard: attribution?.attributionCard || null,
      tipZh:
        (plan.tipZh || '') +
        ' · 已入队批重跑干跑串联' +
        (tick ? ' · ' + (tick.tipZh || '') : '') +
        (attribution?.attributionCard ? ' · ' + attribution.attributionCard.bodyZh : ''),
      toastZh: attribution?.toastZh || tick?.toastZh || enq.toastZh || plan.toastZh,
      softCancelIntact: true,
      noEgress: true,
      dryRun: true,
    };
  }

