  @Post('inbox-delta-cache/curve/alerts/shell-health/weekly-sparkline/day-drill/trend-anomaly/chain-bust-reprobe/itemized-contrast/batch-rerun/resume')
  anomalyBatchRerunResume(
    @Req() req: any,
    @Body() body: { maxSteps?: number } = {},
  ) {
    const tenantId = req?.user?.tenantId || req?.resolvedTenantId || 'default';
    const runStep = (phase: string) => {
      const meta = anomalyContrastRowRerunMeta(phase);
      let step: any = null;
      if (phase === 'bust')
        step = executeSuggestedBustDryRun(tenantId, { force: false, autoHitProbe: false, notifyDryRun: true });
      else if (phase === 'reprobe')
        step = executeSuggestedBustDryRun(tenantId, { force: false, autoHitProbe: true, notifyDryRun: true });
      else if (phase === 'attribution') step = trendDeltaAnomalyAttributionDryRun(tenantId, { multiDay: true });
      else if (phase === 'heal')
        step = maybeChainSlaOverdueSelfHealAfterProbeFail({
          tenantId,
          force: true,
          notifyDryRun: true,
          hitProbe: { probeFailed: true, hitRatePct: 0 },
        });
      else step = meta;
      return { ...meta, step, dryRun: true, noEgress: true };
    };
    const r = resumeAnomalyContrastBatchRerun(tenantId, { maxSteps: body?.maxSteps ?? 8, runStep });
    return { ...r, labelZh: '续跑异常对照行批重跑', dryRun: true, noEgress: true, cancelResumeIntact: true };
  }

